```cpp
#include <iostream>
#include <cmath>
#include <functional>

using namespace std;

std::vector<int> fibonacci_sequence(int n) {
    if (n <= 1) {
        return {1, 1};
    }
    else {
        return fibonacci_sequence(n - 1) + fibonacci_sequence(n - 2);
    }
}

int main() {
    int n = 10;
    fibonacci_sequence.push_back(1);
    fibonacci_sequence.push_back(1);
    for (int i = 2; i <= n; i++) {
        cout << fibonacci_sequence[i] << " ";
    }
    return 0;
}
```

