```cpp
#include <iostream>
#include <cmath>

using namespace std;

int fibonacci(int n) {
    if (n <= 1) return n;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += fibonacci(i);
    }
    return sum;
