def highest_common_ancestor(root, left, right):
    if root is None:
        return None
    if left == root or right == root:
        return root
    else:
        left_ancestor = highest_common_ancestor(root.left, left, right)
        right_ancestor = highest_common_ancestor(root.right, left, right)
